-- Original Lua 5.5 behavioral fixture; assertions are the oracle.
local t=table.create(8,3); assert(next(t)==nil and #t==0)
table.insert(t,3); table.insert(t,1,2); table.insert(t,1)
assert(table.concat(t,',')=='2,3,1')
table.sort(t,function(a,b) return a>b end); assert(table.concat(t,',')=='3,2,1')
assert(table.remove(t,2)==2 and #t==2)
local a={1,2,3,4}; assert(table.move(a,1,3,2)==a)
assert(table.concat(a,',')=='1,1,2,3')
local b={}; table.move(a,2,4,1,b); assert(table.concat(b,',')=='1,2,3')
local p=table.pack(1,nil,3); assert(p.n==3)
local x,y,z=table.unpack(p,1,p.n); assert(x==1 and y==nil and z==3)
a[1.0]='float key'; assert(a[1]=='float key')
assert(not pcall(function() a[0/0]=1 end))
print('ok: tables')
